Insert into VERTICALIZZAZIONIBASE (MODULO,DESCRIZIONE) values ('STC','Se attivo (1) indica che è attivata la comunicazione con il Sistema Territoriale di Comunicazione (STC) ed il back-office diventa un Nodo Locale Applicativo (NLA).');
Insert into VERTICALIZZAZIONIBASE (MODULO,DESCRIZIONE) values ('REPLICAISTANZE','Funzionalità che permette di generare nuove istanze a partire dai dati presenti in una pratica precedentemente salvata.');
