Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_ATTIVO','TIPOPROTOCOLLO','E'' il tipo protocollo attivato (IRIDE,PINDARO,SIGEPRO,GEPROT... vedi l''enumerazione ');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_ATTIVO','TIPODOCUMENTODEFAULT','E'' la tipologia di documento da utilizzare per default per protocollare le istanze o i movimenti pervenuti dal front-office. Il codice dipende dal protocollo attivato. Es. 1=Lettera oppure LET=Lettera...a seconda del protocollo in esame');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_ATTIVO','FLUSSODEFAULT','E'' il flusso di protocollo utilizzato per default per richieste provenienti da FO. Es. A=Arrivo,U=Uscita;I=Interno.');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_ATTIVO','CODICEAMMINISTRAZIONEDEFAULT','E'' il codice amministrazione di SIGePro che rappresenta lo sportello (Es. Ufficio commercio per il software CO).');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PINDARO','OPERATORE','E'' l''operatore da utilizzare per protocollare con PINDARO, deve essere fornito dall''amministratore del protocollo PINDARO.');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PINDARO','CODICEENTE','E'' il codice ente per il quale protocollare, deve essere fornito dall''amministratore del protocollo PINDARO.');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PINDARO','PASSWORD','E'' la password per protocollare in PINDARO, deve essere fornita dall''amministratore del protocollo PINDARO.');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PINDARO','URL','E'' l''URl per invocare il protocollo. Non devono essere specificati i metodi.');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('WS_IMPORTAZIONEISTANZA','STATOISTANZA','Imposta lo stato dell''istanza in base al codice indicato nel parametro. I possibili valori sono quelli contenuti in STATIISTANZA');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_ATTIVO','TIPODOCUMENTODEFAULTBO','E'' la tipologia di documento da utilizzare per default per protocollare le istanze immesse da back-office tramite inserimento rapido,inserimento normale automaticamente protocollate e protocollazione massiva di movimenti. Il codice dipende dal protocollo attivato. Es. 1=Lettera oppure LET=Lettera...');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_ATTIVO','VISUALIZZAUORAGGRUPPATE','può assumere il valore di PROT_UO o PROT_RUOLO. Nei combo relativi ai mittenti e destinatari, qualora si tratti di amministrazioni con PROT_UO e/o PROT_RUOLO impostati,  non saranno visualizzate le amministrazioni di SIGePro ma il campo indicato nel parametro (PROT_UO o PROT_RUOLO) raggruppati per group by. Es. anzichè mostrare le amministrazioni "Ufficio Copia" e "Ufficio Istruttoria" sarà visualizzato "CASTER" che è il nome della PROT_UO associata ad entrambe le amministrazioni');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_ATTIVO','NOALLEGATI','E’ il parametro che permette di stabilire se nella pagina di richiesta protocollo sia presente o meno la sezione per inviare gli allegati della pratica e dei movimenti.Inoltre permette di stabilire se gestire gli allegati o meno nel caso di protocollazione automatiche da BO (Inserimento normale, inserimento rapido e protocollazione massiva di movimenti.  Es. 1=Sezione non presente, 0=Sezione presente');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_ATTIVO','MOVNOPRECOMPILAMITT_DEST','Se 1 allora nella pagina di richiesta protocollo da movimento non verranno precompilati mittenti e/o destinatari');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('I_ATTIVITA','GRUPPOSOFTWARE','E'' possibile indicare la lista dei moduli SOFTWARE che hanno la gestione ATTIVITA'' in comune. Ad esempio per attivare la gestione attività condivisa tra CO e PE devo creare due VERTICALIZZAZIONI I_ATTIVITA una con software CO e una con software PE ed aggiungere ad ognuna di esse un PARAMETRO che sia "CO,PE".');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('SIT_ATTIVO','TIPOSIT','E'' il tipo sit attivato (ESC,CORE,NAUTILUS...) vedi l''enumerazione ');
